#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main(void) {
    double P, R, T;
    if (scanf("%lf %lf %lf", &P, &R, &T) != 3) {
        return 1;
    }
    double SI = (P * R * T) / 100.0;
    // Proper rounding: add 0.005 then truncate
    SI = floor(SI * 100.0 + 0.5) / 100.0;
    printf("%.2f\n", SI);
    return 0;
}
